/**
 * Site-wide constants. Single source of truth for outbound links and contact
 * channels — previously these were hardcoded and duplicated across pages.
 */

/**
 * Canonical host. Apex (stackdrip.dev) 301-redirects here — see the redirect
 * rule in next.config.ts.
 */
export const SITE_URL = "https://www.stackdrip.dev";

export const SITE_NAME = "StackDrip";

/**
 * Site-wide OG/Twitter card, generated by src/app/opengraph-image.tsx.
 * Resolved to an absolute URL against `metadataBase` in the root layout.
 */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "StackDrip — Custom tools for creators, built solo.",
};

/** Checkout for eBay Profit Guardian — the only purchasable product. */
export const GUMROAD_EBAY_URL =
  "https://stackdrip.gumroad.com/l/ebayprofitguardian?wanted=true";

export const CONTACT_EMAIL = "support@stackdrip.dev";

export const TWITTER_HANDLE = "stackdrip";
export const TWITTER_URL = "https://twitter.com/stackdrip";
export const TELEGRAM_URL = "https://t.me/stackdrip";

/** Formspree form ID for the project intake form. */
export const FORMSPREE_INTAKE_ID: string | null = "mgawojnp";

/** WhatsApp number, international format, digits only (UK: 44 + number). */
export const WHATSAPP_NUMBER: string | null = "447375949211";

/** Click-to-chat URL, or null when no number is configured. */
export function whatsappUrl(message?: string): string | null {
  if (!WHATSAPP_NUMBER) return null;
  const base = `https://wa.me/${WHATSAPP_NUMBER}`;
  return message ? `${base}?text=${encodeURIComponent(message)}` : base;
}

export const mailtoUrl = `mailto:${CONTACT_EMAIL}`;

/**
 * Anchor for the homepage contact section. The `contact` id is added to the
 * ContactCTA banner when the homepage is rewritten (phase 5); until then this
 * link lands on the homepage without scrolling.
 */
export const CONTACT_ANCHOR = "/#contact";
